 q=copy.deepcopy(e);glb=R/'experiments-v19'/(key+'-rejected.glb');mother=glb.with_suffix('.blend');q.update(id=key+'-cuff-trial-v19-rejected',name=key.title()+' · 已拒收袖口試作',version='experiment-v19-rejected',variant='rejected',status='rejected-not-for-reuse',baseline_id=e['id'],key=key,warning='已拒收：袖口細分／圓滑化新增表面交叉。僅供重現缺陷，禁止當成正式模板。',model={'url':'../experiments-v19/'+glb.name,'bytes':glb.stat().st_size,'sha256':h(glb)},editable={'path':'experiments-v19/'+mother.name,'sha256':h(mother),'kind':'quarantined editable Blender experiment'},modifications={'status':'rejected','selection':'docs/CUFF_SELECTION_V19.json','mapping':'experiments-v19/mapping.json','images':'All original packed textures/outline mask unchanged','original_vertices':'6648 original rows unchanged; only added cuff vertices/triangles','numerical_compensation':'NOT applied to these GLBs'})
 profile=json.loads((R/e['profile'].removeprefix('../')).read_text());profile.update(version=q['version'],model_sha256=q['model']['sha256'],editable_master_sha256=q['editable']['sha256'],status='rejected-not-for-reuse',source_profile_sha256=e['profile_sha256'],experimental_topology_mapping='experiments-v19/mapping.json');pp=R/'experiments-v19'/(key+'-skeleton-profile.json');write(pp,profile);q.update(profile='../experiments-v19/'+pp.name,profile_sha256=h(pp));experiments.append(q)
 manifest={'schema_version':1,'asset_id':q['id'],'version':q['version'],'model_file':glb.name,'source_file':mother.name,'sha256':q['model']['sha256'],'unit':'meter','clips':[c['name'] for c in e['clips']],'min_animation_count':7,'requirements':{'skins':True,'animated':True,'visual_review':True},'source':q['source_url'],'license_note':'CC0 pixiv; project experiment; THIRD_PARTY_V19.md','status':'rejected-not-for-reuse','art_approved':False,'game_ready':False}
 write(R/'experiments-v19'/(key+'-manifest.json'),manifest)
